"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["73028"],{21280(o){o.exports=JSON.parse('{"registro":{"codigo":"uniplus.configuracao.fato_candidato.eixo_nao_editavel_no_tipo_do_fato","status":422,"titulo":"Eixo que o tipo do fato n\xe3o permite alterar"},"descricao":{"codigo":"uniplus.configuracao.fato_candidato.eixo_nao_editavel_no_tipo_do_fato","requisitos":["UNI-REQ-0159"],"oQueAconteceu":["O administrador enviou a nova defini\xe7\xe3o de um fato do cat\xe1logo (`PUT /api/configuracao/admin/fatos-candidato/{id}/definicao`) informando um eixo que o tipo daquele fato n\xe3o permite alterar. Cada tipo de fato aceita um subconjunto da defini\xe7\xe3o: o fato declarado aceita todos os eixos; o fato derivado por regra aceita o tipo de dado (`dominio`, s\xf3 booleano ou categ\xf3rico), o escopo, o ponto de resolu\xe7\xe3o e a prote\xe7\xe3o de dados, pois a cardinalidade, a origem das op\xe7\xf5es e o formato s\xe3o inferidos do tipo de dado (booleano ou categ\xf3rico), e n\xe3o da regra; o resumo de grupo aceita s\xf3 o ponto de resolu\xe7\xe3o e a prote\xe7\xe3o de dados, pois o restante \xe9 inferido do fato de membro. C\xf3digo, origem e v\xednculo nunca mudam. A corre\xe7\xe3o da defini\xe7\xe3o de um fato \xe9 regra do UNI-REQ-0159.","A recusa vem na lista `errors` da resposta, com `field` igual ao eixo informado a mais (`dominio`, `cardinalidade`, `fonteValores`, `formato` ou `escopo`), uma entrada por eixo. Nada \xe9 gravado."],"comoResolver":["Reenvie a defini\xe7\xe3o sem o eixo apontado: deixe `cardinalidade`, `fonteValores` e `formato` fora do corpo de um fato derivado por regra, e deixe tamb\xe9m `dominio` e `escopo` fora do corpo de um resumo de grupo. O ponto de resolu\xe7\xe3o e a prote\xe7\xe3o de dados s\xe3o enviados sempre, em qualquer tipo de fato; no fato declarado e no derivado por regra, o tipo de dado (`dominio`) e o escopo tamb\xe9m s\xe3o enviados sempre. Se o que voc\xea precisa mudar \xe9 a cardinalidade, a origem das op\xe7\xf5es ou o formato de um derivado por regra, troque o tipo de dado (booleano ou categ\xf3rico), que \xe9 de onde eles s\xe3o inferidos; no resumo de grupo, a mudan\xe7a \xe9 feita no fato de membro.","A defini\xe7\xe3o corrigida vale para os rascunhos e para os processos novos; a vers\xe3o j\xe1 publicada de um processo n\xe3o muda."],"ondeAparece":["Altera\xe7\xe3o da defini\xe7\xe3o de um fato do cat\xe1logo"]},"modulo":{"id":"configuracao","nome":"Configura\xe7\xe3o","assunto":"Fato candidato"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"2b5f8240ef92ed3147f41ca40a325e729f45c7bd"}}')}}]);